/* Disposable labeled-container acceptance only. Never run on University data. */
:ON ERROR EXIT
SET NOCOUNT ON;SET XACT_ABORT ON;
IF DB_NAME()<>N'VetMed-Ops' OR USER_ID(N'paws-calendar-test-runtime') IS NULL THROW 55090,'Synthetic prerequisites required.',1;
IF OBJECT_ID(N'paws.AfcRecordDocument') IS NULL THROW 55090,'AFC_RECORD_DOCUMENT_FEATURE_MISSING',1;
DECLARE @Batch uniqueidentifier=NEWID(),@F uniqueidentifier=NEWID(),@Other uniqueidentifier=NEWID();
INSERT staging.ImportBatch(ImportBatchId,StartedAtUtc,Status,SourceManifestSha256,ImporterVersion,ValidationSummaryJson)VALUES(@Batch,SYSUTCDATETIME(),N'completed',REPLICATE('B',64),N'synthetic-record-documents',N'{}');
INSERT paws.Faculty(FacultyId,RecordType,DisplayName,Active,SourceImportBatchId)VALUES(@F,N'faculty',N'Synthetic self',1,@Batch),(@Other,N'faculty',N'Synthetic other',1,@Batch);
INSERT paws.UserProfile(FirebaseUid,Email,DisplayName,BaseRole,FacultyId,Active,MustChangePassword)VALUES(N'link-admin',N'admin@example.test',N'Synthetic Admin',N'owner',NULL,1,0),(N'link-self',N'self@example.test',N'Synthetic Self',N'faculty',@F,1,0),(N'link-other',N'other@example.test',N'Synthetic Other',N'faculty',@Other,1,0);
DECLARE @Bytes varbinary(max)=0x255044462D73796E746865746963,@Hash varchar(64),@Req uniqueidentifier=NEWID(),@Doc uniqueidentifier,@Afc uniqueidentifier=NEWID();SET @Hash=CONVERT(varchar(64),HASHBYTES('SHA2_256',@Bytes),2);
DECLARE @Upload TABLE(responseJson nvarchar(max));
INSERT @Upload EXEC paws_api.UploadAfcForm @ActorFirebaseUid=N'link-admin',@FacultyId=@F,@RequestId=@Req,@FileName=N'Original.pdf',@PdfBytes=@Bytes,@PdfSha256=@Hash,@PageCount=1;
SET @Doc=TRY_CONVERT(uniqueidentifier,JSON_VALUE((SELECT TOP(1)responseJson FROM @Upload),'$.documentId'));
CREATE TABLE dbo.RecordDocumentTest(FacultyId uniqueidentifier,OtherId uniqueidentifier,DocumentId uniqueidentifier,RecordId uniqueidentifier,Bytes varbinary(max));INSERT dbo.RecordDocumentTest VALUES(@F,@Other,@Doc,@Afc,@Bytes);
ALTER ROLE paws_runtime_afc_record_document ADD MEMBER [paws-calendar-test-runtime];
ALTER ROLE paws_runtime_afc_form ADD MEMBER [paws-calendar-test-runtime];
EXECUTE AS USER=N'paws-calendar-test-runtime';
EXEC paws_api.CreateAfcRecordWithDocument @AfcRecordId=@Afc,@FacultyId=@F,@StartDate='2026-11-01',@EndDate='2026-11-02',@ReasonCode=N'vacation',@Notes=NULL,@ActorFirebaseUid=N'link-admin',@ActorName=N'Forged Name',@RequestId=@Req,@DocumentId=@Doc;
REVERT;
IF NOT EXISTS(SELECT 1 FROM paws.AfcManualRecord WHERE AfcRecordId=@Afc AND FacultyId=@F) OR NOT EXISTS(SELECT 1 FROM paws.AfcRecordDocument WHERE AfcRecordId=@Afc AND DocumentId=@Doc AND FacultyId=@F) THROW 55090,'Exact record/PDF binding failed.',1;
IF NOT EXISTS(SELECT 1 FROM paws.AuditEvent WHERE EventType=N'afc_form_linked' AND EntityId=CONVERT(nvarchar(36),@Afc) AND ActorName=N'Synthetic Admin') THROW 55090,'Recorded identity/audit missing.',1;
DECLARE @Read TABLE(responseJson nvarchar(max),pdfBytes varbinary(max));
EXECUTE AS USER=N'paws-calendar-test-runtime';
INSERT @Read EXEC paws_api.GetAfcForm @ActorFirebaseUid=N'link-self',@DocumentId=@Doc;
REVERT;
IF NOT EXISTS(SELECT 1 FROM @Read WHERE pdfBytes=@Bytes AND JSON_VALUE(responseJson,'$.facultyId')=CONVERT(varchar(36),@F)) THROW 55090,'Self PDF bytes changed.',1;
DECLARE @List TABLE(responseJson nvarchar(max));
INSERT @List EXEC paws_api.ListAfcForms @ActorFirebaseUid=N'link-self',@FacultyId=@F;
IF NOT EXISTS(SELECT 1 FROM @List CROSS APPLY OPENJSON(responseJson,'$.documents') d WHERE JSON_VALUE(d.value,'$.documentId')=CONVERT(varchar(36),@Doc)) THROW 55090,'Own archive list omitted original.',1;
BEGIN TRY EXEC paws_api.GetAfcForm @ActorFirebaseUid=N'link-other',@DocumentId=@Doc;THROW 55090,'Cross-faculty PDF allowed.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>54803 THROW;END CATCH;
BEGIN TRY EXEC paws_api.ListAfcForms @ActorFirebaseUid=N'link-other',@FacultyId=@F;THROW 55090,'Cross-faculty list allowed.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>54801 THROW;END CATCH;
DECLARE @Bad uniqueidentifier=NEWID(),@BadReq uniqueidentifier=NEWID();
BEGIN TRY EXEC paws_api.CreateAfcRecordWithDocument @AfcRecordId=@Bad,@FacultyId=@Other,@StartDate='2026-11-01',@EndDate='2026-11-02',@ReasonCode=N'vacation',@Notes=NULL,@ActorFirebaseUid=N'link-admin',@ActorName=NULL,@RequestId=@BadReq,@DocumentId=@Doc;THROW 55090,'Cross-faculty document link allowed.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>55003 THROW;END CATCH;
IF EXISTS(SELECT 1 FROM paws.AfcManualRecord WHERE AfcRecordId=@Bad) THROW 55090,'Failed link left an AFC.',1;
SET @Bad=NEWID();SET @BadReq=NEWID();
BEGIN TRY EXEC paws_api.CreateAfcRecordWithDocument @AfcRecordId=@Bad,@FacultyId=@F,@StartDate='2026-11-01',@EndDate='2026-11-02',@ReasonCode=N'vacation',@Notes=NULL,@ActorFirebaseUid=N'link-admin',@ActorName=NULL,@RequestId=@BadReq,@DocumentId=@Doc;THROW 55090,'Used document linked again.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>55003 THROW;END CATCH;
IF EXISTS(SELECT 1 FROM paws.AfcManualRecord WHERE AfcRecordId=@Bad) THROW 55090,'Reused document left a new AFC.',1;
INSERT paws.UserProfile(FirebaseUid,Email,DisplayName,BaseRole,Active,MustChangePassword)VALUES(N'link-admin-two',N'admin2@example.test',N'Other Admin',N'owner',1,0);
UPDATE paws.UserProfile SET FacultyId=@Other WHERE FirebaseUid=N'link-self';
BEGIN TRY EXEC paws_api.GetAfcForm @ActorFirebaseUid=N'link-self',@DocumentId=@Doc;THROW 55090,'Relinked identity saw old original.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>54803 THROW;END CATCH;
UPDATE paws.UserProfile SET FacultyId=@F,MustChangePassword=1 WHERE FirebaseUid=N'link-self';
BEGIN TRY EXEC paws_api.GetAfcForm @ActorFirebaseUid=N'link-self',@DocumentId=@Doc;THROW 55090,'Password gate bypassed.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>54801 THROW;END CATCH;
UPDATE paws.UserProfile SET MustChangePassword=0,Active=0 WHERE FirebaseUid=N'link-self';
BEGIN TRY EXEC paws_api.ListAfcForms @ActorFirebaseUid=N'link-self',@FacultyId=@F;THROW 55090,'Inactive actor listed PDF.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>54801 THROW;END CATCH;
UPDATE paws.UserProfile SET Active=1 WHERE FirebaseUid=N'link-self';
UPDATE paws.Faculty SET Active=0 WHERE FacultyId=@F;
BEGIN TRY EXEC paws_api.GetAfcForm @ActorFirebaseUid=N'link-self',@DocumentId=@Doc;THROW 55090,'Inactive faculty downloaded PDF.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>54801 THROW;END CATCH;
UPDATE paws.Faculty SET Active=1 WHERE FacultyId=@F;
UPDATE paws.UserProfile SET BaseRole=N'other_office' WHERE FirebaseUid=N'link-self';
BEGIN TRY EXEC paws_api.ListAfcForms @ActorFirebaseUid=N'link-self',@FacultyId=@F;THROW 55090,'Revoked role listed PDF.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>54801 THROW;END CATCH;
UPDATE paws.UserProfile SET BaseRole=N'faculty' WHERE FirebaseUid=N'link-self';
EXECUTE AS USER=N'paws-calendar-test-runtime';
BEGIN TRY SELECT PdfBytes FROM paws.AfcFormDocument;REVERT;THROW 55090,'Direct binary access allowed.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>229 BEGIN REVERT;THROW;END;END CATCH;REVERT;
GO
CREATE TRIGGER paws.TestRecordDocumentFailure ON paws.AfcRecordDocument AFTER INSERT AS
BEGIN IF EXISTS(SELECT 1 FROM inserted l JOIN paws.AfcManualRecord a ON a.AfcRecordId=l.AfcRecordId WHERE a.Notes=N'force-link-failure') THROW 55098,'Synthetic link failure.',1;END;
GO
DECLARE @F uniqueidentifier=(SELECT FacultyId FROM dbo.RecordDocumentTest),@Bytes varbinary(max)=0x255044462D73796E746865746963,@Hash varchar(64),@Req uniqueidentifier=NEWID(),@Doc uniqueidentifier,@Afc uniqueidentifier=NEWID();SET @Hash=CONVERT(varchar(64),HASHBYTES('SHA2_256',@Bytes),2);
DECLARE @Upload TABLE(responseJson nvarchar(max));INSERT @Upload EXEC paws_api.UploadAfcForm @ActorFirebaseUid=N'link-admin',@FacultyId=@F,@RequestId=@Req,@FileName=N'Failure.pdf',@PdfBytes=@Bytes,@PdfSha256=@Hash,@PageCount=1;
SET @Doc=TRY_CONVERT(uniqueidentifier,JSON_VALUE((SELECT TOP(1)responseJson FROM @Upload),'$.documentId'));
DECLARE @Before int=(SELECT COUNT(*) FROM paws.AuditEvent);
BEGIN TRY EXEC paws_api.CreateAfcRecordWithDocument @AfcRecordId=@Afc,@FacultyId=@F,@StartDate='2026-11-03',@EndDate='2026-11-04',@ReasonCode=N'vacation',@Notes=NULL,@ActorFirebaseUid=N'link-admin-two',@ActorName=NULL,@RequestId=@Req,@DocumentId=@Doc;THROW 55090,'Other uploader unlinked document accepted.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>55003 THROW;END CATCH;
BEGIN TRY EXEC paws_api.CreateAfcRecordWithDocument @AfcRecordId=@Afc,@FacultyId=@F,@StartDate='2026-11-03',@EndDate='2026-11-04',@ReasonCode=N'vacation',@Notes=N'force-link-failure',@ActorFirebaseUid=N'link-admin',@ActorName=NULL,@RequestId=@Req,@DocumentId=@Doc;THROW 55090,'Link failure create succeeded.',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>55098 THROW;END CATCH;
IF EXISTS(SELECT 1 FROM paws.AfcManualRecord WHERE AfcRecordId=@Afc) OR EXISTS(SELECT 1 FROM paws.AfcRecordDocument WHERE DocumentId=@Doc) OR (SELECT COUNT(*) FROM paws.AuditEvent)<>@Before THROW 55090,'Atomic failure left record/link/audit.',1;
IF NOT EXISTS(SELECT 1 FROM paws.AfcFormDocument WHERE DocumentId=@Doc) THROW 55090,'Failed creation deleted archived original.',1;
DROP TRIGGER paws.TestRecordDocumentFailure;
PRINT 'AFC_RECORD_DOCUMENT_SELF_SCOPE_AND_ATOMICITY_OK';
EXEC paws_api.ListChangeHistoryEvents @ActorFirebaseUid=N'link-admin',@Scope=N'dashboard',@StartUtc='0001-01-01',@EndExclusiveUtc='9999-12-31';
PRINT 'HISTORY_ALL_RETAINED_RANGE_OK';
